/**
 * Pricing Page - Whaleal Cart 定价页面
 * Free 计划优先：双安装入口（本站 OAuth + App Store）
 *
 * 多语言：plans / assurance / faqs 全部来自 i18n/dictionaries/pricing.js。
 * 🔴 额度口径只在该字典一处维护，页面不硬编码数字 ⇒ 三语不可能不一致。
 * @author 恒哥
 */
import React from 'react';
import { Link } from 'gatsby';
import Layout from '../components/Layout';
import SEO from '../components/SEO';
import FreeInstallCta from '../components/FreeInstallCta';
import { usePageI18n } from '../i18n';
import pricingCopy from '../i18n/dictionaries/pricing';
import { getSourceParams, trackEvent } from '../utils/analytics';
import {
  SHOPIFY_APP_STORE_URL,
  SHOPIFY_APP_STORE_LABEL,
} from '../constants/brand';
import './page.css';

export default function PricingPage({ pageContext }) {
  // 🔴 归因：/pricing 是**购买意图最强**的页面 —— SEO 带来的流量是否值得，
  //    关键看它有没有进来（而不是只看首页 PV）。用 useEffect 上报，render 期间不碰 window。
  const { locale, localePath, page } = usePageI18n(pageContext);
  React.useEffect(() => {
    trackEvent('pricing_view', { locale, has_source: Boolean(getSourceParams()) });
  }, [locale]);

  const c = pricingCopy[locale] || pricingCopy.en;
  // SEO 走 pages.js（多语言）—— 见 index.js 的说明
  const meta = page.pricing;
  const plans = c.plans.map((p) => ({ ...p, highlighted: p.name === 'Growth' }));

  return (
    <Layout locale={pageContext?.locale}>
      <SEO
        title={meta.metaTitle}
        description={meta.metaDescription}
        pathname="/pricing"
        hrefLang={locale}
      />
      <div className="pricing-page">
        <div className="page-header pricing-header">
          <h1>{c.pageTitle}</h1>
          <p>{c.pageLead}</p>
        </div>

        <FreeInstallCta
          variant="banner"
          title={c.freeCtaTitle}
          className="pricing-free-strip"
          showPricingLink={false}
        />

        <div className="pricing-assurance">
          {c.assurance.map((item) => (
            <div key={item.strong}>
              <strong>{item.strong}</strong>
              <span>{item.span}</span>
            </div>
          ))}
        </div>

        <div className="pricing-grid">
          {plans.map((plan) => (
            <div
              key={plan.name}
              className={`pricing-card ${plan.highlighted ? 'pricing-card-featured' : ''} ${plan.isFree ? 'pricing-card-free' : ''}`}
            >
              {plan.badge && <div className="pricing-card-badge">{plan.badge}</div>}
              <div className="pricing-card-header">
                <h2>{plan.name}</h2>
                <div className="pricing-price">
                  <span className="pricing-amount">{plan.price}</span>
                  <span className="pricing-period">{plan.period}</span>
                </div>
                <p className="pricing-description">{plan.description}</p>
              </div>

              <ul className="pricing-features">
                {plan.features.map((feature) => (
                  <li key={feature} className="pricing-feature-item">
                    <span className="pricing-feature-check">✓</span>
                    {feature}
                  </li>
                ))}
              </ul>

              <Link
                to={localePath('/install/')}
                className={`pricing-cta ${plan.highlighted || plan.isFree ? 'pricing-cta-primary' : ''}`}
              >
                {plan.cta}
              </Link>
              {plan.isFree && (
                <a
                  href={SHOPIFY_APP_STORE_URL}
                  className="pricing-cta pricing-cta-store"
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  {c.storeAlt.replace('{store}', SHOPIFY_APP_STORE_LABEL)}
                </a>
              )}
            </div>
          ))}
        </div>

        <div className="pricing-faq pricing-faq-block">
          <h2>{c.faqTitle}</h2>
          {c.faqs.map((item) => (
            <div key={item.q} className="pricing-faq-item">
              <h3>{item.q}</h3>
              <p>{item.a}</p>
            </div>
          ))}
          <p className="pricing-faq-more">
            {c.faqMoreLead} <Link to={localePath('/help/')}>{c.faqMoreLink}</Link>
          </p>
        </div>

        <div className="pricing-actions pricing-actions-block">
          <FreeInstallCta variant="card" title={c.bottomTitle} showPricingLink={false} />
        </div>
      </div>
    </Layout>
  );
}